const raw = $input.first().json.choices[0].message.content;
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  return [{ json: { _valid: false, _raw: cleaned, _error: err.message } }];
}
return [{ json: { _valid: true, generation_run_id: $('Set Business Context').first().json.generation_run_id, agent: 'positioning', positioning_output: parsed } }];

const raw = $input.first().json.choices[0].message.content;
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  return [{ json: { _valid: false, _raw: cleaned, _error: err.message } }];
}
return [{ json: { _valid: true, generation_run_id: $('Set Business Context').first().json.generation_run_id, agent: 'icp', icp_output: parsed } }];

const body = $input.first().json.body || {};
const required = ['company_name', 'core_customer_problem'];
const missing = required.filter(f => !body[f] || String(body[f]).trim() === '');

if (missing.length > 0) {
  return [{ json: { _valid: false, _error: 'Missing required fields: ' + missing.join(', ') } }];
}
return [{ json: { ...$input.first().json, _valid: true } }];

const d = $('Set Business Context').first().json;
const marketingStage = d.marketing_stage || 'Brand Awareness (Top of Funnel)';

const positioningBody = {
  model: 'deepseek/deepseek-v4-flash',
  temperature: 0.2,
  top_p: 0.1,
  response_format: { type: 'json_object' },
  provider: { order: ['Together', 'AtlasCloud', 'Venice'], allow_fallbacks: true },
  messages: [
    {
      role: 'system',
      content: 'You are an elite B2B product positioning strategist. Your job is to define the ROLE this product plays in a customer life, not to restate its features, and to deliberately choose which category the company should own rather than defaulting to the obvious one implied by the product description. Before writing the JSON, silently reason through: (0) generate 4 distinct candidate categories this company could credibly own, including at least one that reframes the market rather than describing the literal product type, (1) what does the product literally do, (2) which of those capabilities actually matters to the customer, (3) what does life look like before versus after using it, (4) for each candidate category apply this durability test: would this category definition still make sense if the product doubled its feature set two years from now. Reject any candidate that only works for the current feature set. Select the candidate that passes the durability test and best matches the customer transformation, and use it as category_definition. Never let a feature or mechanism become the subject of a differentiation_pillars sentence or the positioning_statement unique benefit clause; pillars must describe an outcome or transformation the company uniquely delivers, never a capability. Test each pillar: if the sentence could appear unchanged on a features or product page, it fails and must be rewritten as an outcome. BAD pillar: Auto-applies to jobs on your behalf. GOOD pillar: Gives you your evenings back by taking the job search off your plate. (5) using the category_definition selected in step 4, generate 5 candidate pillars that specifically reinforce that category rather than reading as generic claims about the product, each an outcome or transformation, then for each one explicitly name-check it against every named competitor provided: would that named competitor, in their own marketing, plausibly say almost this exact sentence about themselves. Write down the verdict for each candidate. Any candidate a named competitor could plausibly claim is table stakes, not differentiation, and must be marked rejected even if it sounds good. From the candidates that survive, select and order the final 3 from hardest-for-a-named-competitor-to-copy to easiest. If fewer than 3 candidates survive, generate more candidates until 3 survive rather than reusing a rejected one. (6) using the category_definition from step 4 and the differentiation_pillars that survive step 5, compress those specific choices into one sentence under 8 words that a customer could repeat word for word to a friend after hearing the pitch a single time, with zero additional explanation needed for it to land; draft 3 candidates for this and keep only the one that needs no follow-up sentence to make sense. Reject any candidate that is generic enough to apply to a different company in the same market. (7) using the category_definition from step 4 and the differentiation_pillars from step 5 as the concrete evidence, articulate the underlying belief this brand should hold about how the category should work, using these as calibration references, not as content to copy: Linear believes software should feel like magic, Superhuman believes time is your most valuable asset, Stripe believes the goal is to increase the GDP of the internet, Notion believes software should be as flexible as paper. Write one original belief in that register for this specific company, grounded in its actual customer problem, not a generic restatement of the product description. (8) using the differentiation_pillars from step 5 as the concrete evidence for which side this brand is already on, name the central strategic tension this brand should explicitly choose a side on, using these as calibration references: Notion chose simple over enterprise-complex, Superhuman chose speed over feature completeness, Figma chose browser-based over desktop-native. The tension must be a real trade-off where a reasonable competitor could credibly choose the opposite side; do not describe both sides neutrally, commit to one. Output ONLY valid JSON. SCHEMA: {"category_candidates":["exactly 4 strings, each formatted as CategoryName - one-line reason it was considered or rejected, stating whether it passed the durability test"],"category_definition":"string under 12 words, must be the winning candidate from category_candidates","positioning_statement":"For [target customer] who [specific problem], [company] is the [category] that [unique benefit], unlike [main alternative] which [key weakness]","before_after_transformation":"string formatted exactly as Before: [one concrete sentence describing the current painful day-to-day state for that customer, with specific time or effort detail, not an abstract adjective]. After: [one concrete sentence describing life once the product is adopted, equally specific]","pillar_candidates":["exactly 5 strings, each formatted as: the candidate pillar sentence, then a dash, then REJECTED plus the name of the competitor who could plausibly claim it, or SURVIVED plus why no named competitor could plausibly claim it"],"differentiation_pillars":["exactly 3 strings taken only from pillar_candidates entries marked SURVIVED, ordered from hardest-to-replicate to easiest-to-replicate, each describing a customer-facing outcome or transformation the company uniquely delivers, never a feature, mechanism, or capability, and never appearing unchanged on a features or product page"],"market_framing_strategy":"one sentence under 25 words usable verbatim in a sales email, framed as an outcome not a feature","memorable_hook":"the single winning candidate from step 6: under 8 words, no jargon, repeatable verbatim after one hearing, and specific enough that it would not fit a different company in the same market","brand_philosophy":"one original sentence stating the belief this brand holds about how the category should work, in the register of the calibration references from step 7, grounded in this specific customer problem, never a restatement of the product description","strategic_tension":"string formatted as [side this brand takes] over [side it explicitly rejects], naming a real trade-off in the register of the calibration references from step 8, where a reasonable competitor could credibly have chosen the opposite side"}'
    },
    {
      role: 'user',
      content: 'Generate positioning for this company only. Company: ' + d.company_name + ' Product: ' + d.product_description + ' Target audience: ' + d.target_audience + ' Competitors: ' + d.primary_competitors + ' Customer problem: ' + d.core_customer_problem + ' Desired outcome: ' + d.desired_outcome + ' Business model: ' + d.business_model + ' Unique differentiators: ' + d.unique_differentiators + ' Marketing stage: ' + marketingStage + ' Return JSON with category_definition, positioning_statement, before_after_transformation, differentiation_pillars, market_framing_strategy, memorable_hook, brand_philosophy, strategic_tension.'
    }
  ]
};

const icpBody = {
  model: 'deepseek/deepseek-v4-flash',
  temperature: 0.2,
  top_p: 0.1,
  response_format: { type: 'json_object' },
  provider: { order: ['Together', 'AtlasCloud', 'Venice'], allow_fallbacks: true },
  messages: [
    {
      role: 'system',
      content: 'You are an elite B2B customer intelligence analyst. Demographic traits like age, job title, company size, and industry are weak predictors of who actually buys; behavior is what predicts purchase. Lead with what the person already does, how urgently they need the outcome, and what they have already tried, before any demographic detail. Output ONLY valid JSON. SCHEMA: {"behavioral_signals":["exactly 5 specific observable behaviors or habits that indicate someone is in-market right now, phrased as things the person already does, for example already customizes materials by hand, does the core task weekly, has been actively working the problem for 60 plus days, prioritizes quality over volume, is already paying for or trialing an adjacent tool"],"primary_target_persona":"string led by the behavioral profile from behavioral_signals; job function and career stage may follow as light context; only mention age range or company size if it is genuinely load-bearing for this product, and if mentioned it must come after the behavioral description, never first","adoption_pattern":"string explaining top-down or bottom-up and why","buying_triggers":["exactly 5 triggers that move someone from passive to actively shopping; at least 2 must be emotional or psychological states the person would say about themselves, such as feeling exhausted, feeling stuck, losing confidence, or comparing themselves to peers who are succeeding, phrased in first person or as a felt state rather than a circumstance; the rest may be functional or circumstantial events; do not make all 5 purely circumstantial"],"customer_fears_and_risks":["exactly 3 product-specific fears"],"economic_buyer_profile":"string with exact title, company size range, annual budget authority in dollars"}. IMPORTANT: Do not default to enterprise buyers. Match the ICP to the actual business model and target audience provided. If the product targets prosumers, SMBs, or individual professionals, reflect that accurately. Do NOT use generic placeholder titles like IT Project Manager, Business Analyst, or Operations Manager unless the product description explicitly names those roles as the target user.'
    },
    {
      role: 'user',
      content: 'Generate ICP for this company only. Company: ' + d.company_name + ' Product: ' + d.product_description + ' Target audience: ' + d.target_audience + ' Competitors: ' + d.primary_competitors + ' Customer problem: ' + d.core_customer_problem + ' Business model: ' + d.business_model + ' Unique differentiators: ' + d.unique_differentiators + ' Marketing stage: ' + marketingStage + ' IMPORTANT: The ICP must reflect ALL segments of the target audience provided, not just enterprise buyers. Lead with behavioral_signals before any demographic detail. Include exact budget figures in the economic buyer profile. Return JSON with behavioral_signals array of exactly 5, primary_target_persona, adoption_pattern, buying_triggers array of exactly 5, customer_fears_and_risks array of exactly 3, economic_buyer_profile.'
    }
  ]
};

return [{
  json: {
    generation_run_id: d.generation_run_id,
    company_name: d.company_name,
    marketing_stage: marketingStage,
    positioning_body: positioningBody,
    icp_body: icpBody
  }
}];
